def alphabetic_sum_product(words, target):

  def alphabetical_sum(word):
    return sum(ord(c) - ord('a') + 1 for c in word)

  sums = set()
  for word in words:
    sums.add(alphabetical_sum(word))

  for i in sums:
    if target % i != 0:
      continue
    for j in sums:
      k = target / (i * j)
      if k in sums:
        return True
  return False

