    return [...word].reduce(
      (sum, c) => sum + c.charCodeAt(0) - "a".charCodeAt(0) + 1,
      0,
    );
  }
  const sums = new Set();
  for (const word of words) {
    sums.add(alphabeticalSum(word));
  }

  for (const i of sums) {
    if (target % i !== 0) {
      continue;
